revisions.render_css:
* { box-sizing: border-box; }
.card--experience-refraction {
  --ink: #050A12;
  --paper: #F4F1E8;
  --muted: #91A5B2;
  --success: #4FD4C0;
  --failure: #FF765C;
  --judgment: #E7C97F;
  position: relative;
  isolation: isolate;
  width: 1080px;
  height: 1350px;
  margin: 0;
  overflow: hidden;
  color: var(--paper);
  background: var(--ink);
  font-family: 'Apple SD Gothic Neo', 'Noto Sans KR', 'Malgun Gothic', Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-rendering: geometricPrecision;
}
.card--experience-refraction::before {
  content: '';
  position: absolute;
  z-index: 3;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(circle at 55% 59%, transparent 31%, rgba(1, 4, 8, .13) 67%, rgba(1, 3, 7, .78) 112%);
}
.card--experience-refraction::after {
  content: '';
  position: absolute;
  z-index: 8;
  inset: 18px;
  pointer-events: none;
  border: 1px solid rgba(224, 237, 238, .08);
}
.card--experience-refraction .card__scene {
  position: absolute;
  z-index: 1;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}
.card--experience-refraction .card__copy {
  position: absolute;
  z-index: 6;
  top: 78px;
  left: 80px;
  width: 900px;
}
.card--experience-refraction .card__eyebrow {
  display: flex;
  align-items: center;
  width: max-content;
  max-width: 760px;
  color: #B7C3C8;
  font-size: 22px;
  font-weight: 650;
  line-height: 1.35;
  letter-spacing: .04em;
  white-space: nowrap;
}
.card--experience-refraction .card__eyebrow::before {
  content: '';
  width: 10px;
  height: 10px;
  margin-right: 14px;
  border: 2px solid var(--judgment);
  transform: rotate(45deg);
  box-shadow: 0 0 18px rgba(231, 201, 127, .34);
}
.card--experience-refraction .card__eyebrow::after {
  content: '';
  width: 112px;
  height: 1px;
  margin-left: 20px;
  background: linear-gradient(90deg, rgba(183, 195, 200, .6), transparent);
}
.card--experience-refraction .card__headline {
  max-width: 850px;
  margin: 38px 0 0;
  color: var(--paper);
  font-size: 94px;
  font-weight: 820;
  line-height: .99;
  letter-spacing: -.058em;
  word-break: keep-all;
  overflow-wrap: normal;
  white-space: pre-line;
  text-wrap: balance;
  text-shadow: 0 8px 35px rgba(0, 0, 0, .46);
}
.card--experience-refraction .card__headline::after {
  content: '';
  display: block;
  width: 282px;
  height: 2px;
  margin-top: 32px;
  background: linear-gradient(90deg, var(--judgment), rgba(231, 201, 127, .18), transparent);
  box-shadow: 0 0 16px rgba(231, 201, 127, .25);
}
.card--experience-refraction .card__folio {
  position: absolute;
  z-index: 7;
  right: 72px;
  bottom: 62px;
  display: flex;
  align-items: center;
  color: var(--paper);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 3px 16px rgba(0, 0, 0, .8);
}
.card--experience-refraction .card__position {
  font-size: 52px;
  font-weight: 760;
  line-height: 1;
  letter-spacing: -.045em;
}
.card--experience-refraction .card__folio-rule {
  width: 46px;
  height: 1px;
  margin: 0 15px;
  background: var(--judgment);
  transform: rotate(-56deg);
  transform-origin: center;
  box-shadow: 0 0 12px rgba(231, 201, 127, .38);
}
.card--experience-refraction .card__count {
  align-self: flex-end;
  margin-bottom: 5px;
  color: #AAB9C1;
  font-size: 20px;
  font-weight: 650;
  line-height: 1;
  letter-spacing: .06em;
}

.card{position:relative;width:1080px;height:1350px;overflow:hidden;box-sizing:border-box;font-family:"Pretendard Variable",Pretendard,-apple-system,BlinkMacSystemFont,"Apple SD Gothic Neo","Noto Sans KR","Malgun Gothic",sans-serif;background:var(--cream);color:var(--ink);--ink:#14171A;--sub:#43463F;--muted:#8F9088;--cream:#F8F7F2;--panel:#EFEDE3;--line:#DBD8CC;--green:#1F6B4E;--green-soft:#DFEAE2;--amber:#D9822B;--amber-soft:#F6E8D4;--dark:#0B0F0D;-webkit-font-smoothing:antialiased}
.card,.card *{box-sizing:border-box;margin:0;padding:0}
.card--light{padding:104px 96px 150px;display:flex;flex-direction:column}
.head{display:flex;justify-content:space-between;align-items:center}
.sig{font-size:25px;font-weight:600;letter-spacing:.14em;color:var(--muted)}
.num{display:block;margin-top:40px;font-size:148px;line-height:1;font-weight:900;letter-spacing:-.02em;color:var(--green)}
.num--amber{color:var(--amber)}
.headline{margin-top:28px;font-size:74px;line-height:1.18;font-weight:800;letter-spacing:-.015em;white-space:pre-line;color:var(--ink)}
.num+.headline{margin-top:14px}
.body{margin-top:28px;font-size:34px;line-height:1.62;font-weight:500;color:var(--sub);max-width:860px}
.pager{position:absolute;right:96px;bottom:70px;font-size:24px;font-weight:700;letter-spacing:.08em;color:var(--muted)}
.pager--light{color:rgba(255,255,255,.55)}
.scene{margin-top:auto;background:var(--panel);border:2px solid var(--line);border-radius:36px;padding:20px;overflow:hidden}
.scene svg{display:block;width:100%;height:auto}
.card--cover{background:var(--dark);color:#fff;padding:104px 96px 150px;display:flex;flex-direction:column}
.cover-bg{position:absolute;inset:0;width:100%;height:100%}
.cover-top{position:relative}
.cover-eyebrow{display:inline-flex;align-items:center;gap:18px;font-size:26px;font-weight:600;letter-spacing:.16em;color:#9BA69E}
.cover-eyebrow::before{content:"";width:56px;height:3px;background:#58B08B}
.cover-headline{position:relative;margin-top:auto;font-size:116px;line-height:1.14;font-weight:900;letter-spacing:-.02em;white-space:pre-line;color:#FCFCF8}
.cover-rule{position:relative;margin-top:36px;width:128px;height:6px;background:#58B08B}
.card--context .ab{display:flex;align-items:stretch;margin:56px 0 20px}
.ab-panel{flex:1;background:var(--panel);border:2px solid var(--line);border-radius:32px;padding:26px;display:flex;align-items:center;justify-content:center}
.ab-panel svg{display:block;width:100%;height:auto}
.ab-mid{align-self:center;width:104px;text-align:center;font-size:64px;font-weight:900;color:var(--amber)}
.card--context .body{margin-top:44px}
.img-frame{position:relative;margin-top:auto;height:470px;border-radius:36px;overflow:hidden;border:2px solid var(--line);background:#fff}
.src-img{width:100%;height:100%;object-fit:cover;display:block}
.loop-badge{position:absolute;top:24px;right:24px;width:110px;height:110px;filter:drop-shadow(0 6px 14px rgba(0,0,0,.35))}
.fit{display:flex;gap:32px;margin-top:auto}
.fit-panel{flex:1;border-radius:36px;padding:16px;border:2px solid var(--line)}
.fit-panel svg{display:block;width:100%;height:auto}
.fit-yes{background:var(--green-soft);border-color:#C4D8CB}
.fit-no{background:var(--amber-soft);border-color:#E5CBA6}
.card--warning{background:#F7F1E6}
.hazard{position:absolute;top:0;left:0;right:0;height:24px;background:repeating-linear-gradient(-45deg,#D9822B 0 24px,#14171A 24px 48px)}
.scene--warn{background:#F4E7CF;border-color:#E2CBA0}
.sheet{position:relative;margin-top:64px;background:#fff;border:2px solid var(--line);border-radius:36px;padding:88px 56px 64px 60px;display:flex;gap:44px;align-items:center;box-shadow:0 18px 0 rgba(20,23,26,.05)}
.sheet-clip{position:absolute;top:-18px;left:50%;width:124px;height:46px;transform:translateX(-50%)}
.check-col{display:flex;flex-direction:column;gap:38px;flex:none}
.check-dot{width:78px;height:78px;display:block}
.sheet-body{margin-top:0;font-size:36px;line-height:1.9;max-width:none}
.under-pen{margin-top:auto;width:100%;height:120px;display:block}
.card--close{background:var(--dark)}
.card--close .sig{color:#7E8C82}
.card--close .headline{margin-top:44px;font-size:92px;color:#F5F6F1}
.card--close .body{margin-top:40px;color:#B9C1B8}
.close-scene{margin-top:auto}
.close-scene svg{display:block;width:100%;height:auto}
